import{_ as t,o as i,c as a,ag as o}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/image49.png",r="/nada-documentation/images/image50.png",s="/nada-documentation/images/image51.png",f=JSON.parse('{"title":"Login","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/login.md","filePath":"admin-guide/web-ui/login.md","lastUpdated":1786379412000}'),l={name:"admin-guide/web-ui/login.md"};function d(p,e,c,h,m,g){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="login" tabindex="-1">Login <a class="header-anchor" href="#login" aria-label="Permalink to &quot;Login&quot;">​</a></h1><h2 id="using-the-administrator-interface" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>A login link is provided at the top-right of the NADA catalog site. This login will be used by administrators to access the administrator interface, or by registered users who need to login to request access to non- public datasets. The administrator interface will only be accessible to users who have been granted some administrative role in the catalog (full administrator, collection administrator, reviewer, or data request approver; the specific administrator privileges are defined by the full administrator in the &quot;Users&quot; section of the administrator interface).</p><p><img src="'+n+'" alt=""></p><p>After login as administrator, the login button will display a menu as follows.</p><p><img src="'+r+'" alt=""></p><p>The Site administration link will open the administrator interface (&quot;Dashboard&quot;).</p><p>The Profile link will display your profile, with an option to edit its content and to generate your API keys. An API key will be required to programmatically add, edit, extract, or delete information from the NADA catalog, using R or Python for example. The privileges that the API key will provide depend on the permissions you have to administer the catalog or specific component of it.</p><p>API keys, especially those with administrator privileges attached to them, are like your password and must be kept strictly confidential. If you have any reason to believe that your key has been compromised, cancel it immediately, and generate a new key.</p><p><img src="'+s+'" alt=""></p><h2 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>The profile can only be edited in the administrator interface.</p><p>The equivalent of login when using the API is to provide the URL and entering your key.</p><p>In R:</p><p>set_api_key</p><p>set_api_url</p><p>set_api_verbose</p><p>In Python:</p><p>Note: restricting the API use to certain IP addresses.</p>',19)])])}const _=t(l,[["render",d]]);export{f as __pageData,_ as default};
